#include <iostream>
#include <limits>
#include <optional>
std::optional<int> increment(int value) {
    if (value == std::numeric_limits<int>::max()) return std::nullopt;
    return value + 1;
}
int main() {
    const auto ordinary = increment(7);
    const auto boundary = increment(std::numeric_limits<int>::max());
    std::cout << "ordinary=" << *ordinary << '\n';
    std::cout << std::boolalpha << "maximum rejected="
              << !boundary.has_value() << '\n';
    const unsigned wrapped = std::numeric_limits<unsigned>::max() + 1u;
    std::cout << "unsigned wrap=" << wrapped << '\n';
}

#include <iostream>
int main() {
    const unsigned count = 17u;
    const unsigned width = 16u;
    const unsigned exact = count * width; // 272 fits unsigned.
    const unsigned eight_bit_model = exact & 255u;
    const unsigned policy_limit = 64u;
    std::cout << "modeled narrow bytes=" << eight_bit_model << '\n';
    std::cout << std::boolalpha << "narrow check accepts="
              << (eight_bit_model <= policy_limit) << '\n';
    std::cout << "exact bytes=" << exact << '\n';
    std::cout << "correct check accepts="
              << (count <= policy_limit / width) << '\n';
}

